using System;using System.IO;using UnityEditor;using UnityEditor.Build.Reporting;using UnityEngine;using CityForge.World;
namespace CityForge.Editor {
[InitializeOnLoad] public static class HillsMountainTestTools {
static HillsMountainTestTools(){EditorApplication.update+=Tick;}
static void Tick(){const string request="Library/MountainTest.request";if(EditorApplication.isCompiling||EditorApplication.isUpdating||MountainAcceptance.Running||!File.Exists(request))return;var action=File.ReadAllText(request).Trim();if(action=="build"){if(EditorApplication.isPlaying){EditorApplication.isPlaying=false;return;}File.Delete(request);Build();return;}EditorApplication.isPaused=false;File.Delete(request);if(!EditorApplication.isPlaying){EditorApplication.isPlaying=true;File.WriteAllText(request,action);return;}if(action=="open")Open();else new GameObject("Mountain acceptance").AddComponent<MountainAcceptance>();}
[MenuItem("CityForge/Terrain/Create And Open Hills And Mountain Test")]
public static void Open(){if(!EditorApplication.isPlaying)throw new Exception("Play MainMenu first.");EditorCoroutineRunner.Begin(OpenSaved());}
static System.Collections.IEnumerator OpenSaved(){var old=UnityEngine.Object.FindFirstObjectByType<PrototypeRegionView>();if(old)old.ReturnToMenu();yield return null;yield return null;var path=Path.Combine(SavedRegionStore.DirectoryPath,HillsMountainTestRegion.Id+".cfregion");if(!File.Exists(path))SavedRegionStore.Save(HillsMountainTestRegion.Generate());var saved=SavedRegionStore.Load(path);PrototypeRegionView.Open(saved.info.name,UnityEngine.Object.FindFirstObjectByType<Canvas>(),snapshot:saved);var view=UnityEngine.Object.FindFirstObjectByType<PrototypeRegionView>();view.ApprovedDistrict.SetTreesEnabled(true);view.ApprovedDistrict.SetSmallPlantsEnabled(true);view.ApprovedDistrict.SetFramePacing60(true);var rocks=view.ApprovedDistrict.GetComponent<MountainRockRenderer>();if(rocks.OutcropCount!=0||rocks.ScreeCount!=68)throw new Exception("Outcrop removal changed loose-stone placements");Debug.Log($"PASS mountain cleanup: {rocks.OutcropCount} large outcrops, {rocks.ScreeCount} original loose stones retained.");}
[MenuItem("CityForge/Terrain/Run Mountain Acceptance Checks")]
static void Check(){if(!EditorApplication.isPlaying)throw new Exception("Play MainMenu first.");new GameObject("Mountain acceptance").AddComponent<MountainAcceptance>();}
[MenuItem("CityForge/Terrain/Build Mountain Verification Player")]
public static void Build(){var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/CityForge/Scenes/Gameplay/MainMenu.unity"},target=BuildTarget.StandaloneOSX,locationPathName="/Users/joelinstrum/Documents/Codex/2026-10-12/begin-from-this-handoff-and-start/work/MountainVerification.app",options=BuildOptions.Development});File.WriteAllText(MountainAcceptance.Output+"Mountain-Five-Steps-Build.txt",$"{result.summary.result}; errors={result.summary.totalErrors}; warnings={result.summary.totalWarnings}; duration={result.summary.totalTime}\n");if(result.summary.result!=BuildResult.Succeeded)throw new Exception("Mountain build failed");}
}
}
